// Encoding and resolution conversion only; artwork is generated by image_gen.
const fs=require('node:fs'),path=require('node:path');
const sharp=require('C:/Users/123/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/sharp');
const root=path.resolve(__dirname,'../..');
const input='C:/Users/123/.codex/generated_images/01a16bd0-8fc1-74a1-ac57-1e45c185e153';
const files={breakfast:'exec-1271521c-5671-47fe-a6ce-a9b53f4a2c43.png',barbecue:'exec-4f787e85-666d-47ad-9348-39dcbf81cce7.png',countryside:'exec-be1e4647-64e8-41d6-9e5d-fbff9dd00679.png',grocery:'exec-4078764f-0453-4fb7-be16-20d22d81e450.png',toys:'exec-d463d84a-58dd-419e-ae26-f012fa16505a.png'};
const source=path.join(root,'source-assets/ui/home-theme-v1'),out=path.join(root,'projects/catch-big-goose-unity/Assets/Resources/Textures/mobile-ui/themes');
async function main(){
  fs.mkdirSync(source,{recursive:true});
  for(const [id,file]of Object.entries(files)){
    const master=path.join(source,id+'-master.png');if(!fs.existsSync(master))fs.copyFileSync(path.join(input,file),master);
    const jpeg=await sharp(master).resize(768,1152,{kernel:'lanczos3'}).jpeg({quality:90,chromaSubsampling:'4:4:4'}).toBuffer();
    fs.writeFileSync(path.join(out,id+'-v1.bytes'),jpeg);
    for(const suffix of ['.jpg','.jpg.meta']){const old=path.join(out,id+'-v1'+suffix);if(fs.existsSync(old)){const retired=path.join(source,'retired-imported-v1');fs.mkdirSync(retired,{recursive:true});fs.renameSync(old,path.join(retired,id+'-v1'+suffix));}}
    // Retired Resources are kept outside Assets so they don't inflate the game.
    const archive=path.join(source,'retired-r4');fs.mkdirSync(archive,{recursive:true});
    for(const suffix of ['.png','.png.meta']){const old=path.join(out,id+'-r4'+suffix);if(fs.existsSync(old))fs.renameSync(old,path.join(archive,id+'-r4'+suffix));}
  }
  const data=path.join(root,'projects/catch-big-goose-unity/Assets/Resources/Data');
  for(const file of ['themes.json','reference-lab.json']){const p=path.join(data,file);fs.writeFileSync(p,fs.readFileSync(p,'utf8').replace(/themes\/(breakfast|barbecue|countryside|grocery|toys)-r4/g,'themes/$1-v1'));}
  console.log('Five generated background masters and runtime JPEGs saved.');
}
main().catch(e=>{console.error(e);process.exit(1)});
